		begin
			_sv2v_jump = 2'b00;
			if (fp8_is_nan(a[6:0]) || fp8_is_nan(b[6:0])) begin
				fp8_add = FP8_QNAN;
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				hi_operand = (a[6:0] >= b[6:0] ? a : b);
				lo_operand = (a[6:0] >= b[6:0] ? b : a);
				el = (hi_operand[6:3] == 0 ? 5'd1 : {1'b0, hi_operand[6:3]});
				es = (lo_operand[6:3] == 0 ? 5'd1 : {1'b0, lo_operand[6:3]});
				ml = {hi_operand[6:3] != 0, hi_operand[2:0]};
				ms = {lo_operand[6:3] != 0, lo_operand[2:0]};
				aligned = fp8_jam8({1'b0, ms, 3'b000}, el - es);
				subtract = hi_operand[7] ^ lo_operand[7];
				total = ({1'b0, ml, 3'b000} + (aligned ^ {8 {subtract}})) + sv2v_cast_8(subtract);
				if (total == 0) begin
					fp8_add = (a[7] && b[7] ? 8'h80 : FP8_ZERO);
					_sv2v_jump = 2'b11;
				end
				if (_sv2v_jump == 2'b00) begin
					exponent = el;
					if (total[7]) begin
						total = fp8_jam8(total, 5'd1);
						exponent = exponent + 1'b1;
					end
					casez (total[6:0])
						7'b1zzzzzz: leading_zeros = 0;
						7'b01zzzzz: leading_zeros = 1;
						7'b001zzzz: leading_zeros = 2;
						7'b0001zzz: leading_zeros = 3;
						7'b00001zz: leading_zeros = 4;
						7'b000001z: leading_zeros = 5;
						default: leading_zeros = 6;
					endcase
					normalize_shift = ({2'b00, leading_zeros} < exponent ? leading_zeros : sv2v_cast_3(exponent - 1'b1));
					total = total << normalize_shift;
					exponent = exponent - {2'b00, normalize_shift};
					rounded = {1'b0, total[6:3]} + sv2v_cast_5(total[2] && ((total[1] || total[0]) || total[3]));
					if (rounded[4]) begin
						rounded = rounded >> 1;
						exponent = exponent + 1'b1;
					end
					if ((exponent > 15) || ((exponent == 15) && (rounded > 14))) begin
						fp8_add = {hi_operand[7], 7'h7e};
						_sv2v_jump = 2'b11;
					end
					if (_sv2v_jump == 2'b00) begin
						if ((exponent == 1) && (rounded < 8)) begin
							fp8_add = {hi_operand[7], 4'b0000, rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
						if (_sv2v_jump == 2'b00) begin
							fp8_add = {hi_operand[7], exponent[3:0], rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
					end
				end
			end
		end
	endfunction
	function automatic signed [3:0] sv2v_cast_4_signed;
		input reg signed [3:0] inp;
		sv2v_cast_4_signed = inp;
	endfunction
	function automatic [7:0] fp8_pack8;
		input reg sign;
		input reg [7:0] magnitude;
		input reg signed [6:0] scale;
		reg [2:0] msb;
		reg signed [6:0] exponent;
		reg signed [6:0] shift;
		reg [3:0] retained;
		reg [3:0] encoded;
		reg guard_bit;
		reg sticky;
		reg [4:0] rounded;
		reg [0:1] _sv2v_jump;
		begin
			_sv2v_jump = 2'b00;
			if (magnitude == 0) begin
				fp8_pack8 = {sign, 7'b0000000};
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				casez (magnitude)
					8'b1zzzzzzz: msb = 7;
					8'b01zzzzzz: msb = 6;
					8'b001zzzzz: msb = 5;
					8'b0001zzzz: msb = 4;
					8'b00001zzz: msb = 3;
					8'b000001zz: msb = 2;
					8'b0000001z: msb = 1;
					default: msb = 0;
				endcase
				exponent = $signed({4'b0000, msb}) + scale;
				if (exponent > 8) begin
					fp8_pack8 = {sign, 7'h7e};
					_sv2v_jump = 2'b11;
				end
				if (_sv2v_jump == 2'b00) begin
					shift = (exponent >= -6 ? $signed({4'b0000, msb}) - 7'sd3 : -(7'sd9 + scale));
					retained = 0;
					guard_bit = 0;
					sticky = 0;
					case (shift)
						-7'sd3: retained = {magnitude[0], 3'b000};
						-7'sd2: retained = {magnitude[1:0], 2'b00};
						-7'sd1: retained = {magnitude[2:0], 1'b0};
						0: retained = magnitude[3:0];
						1: begin
							retained = magnitude[4:1];
							guard_bit = magnitude[0];
						end
						2: begin
							retained = magnitude[5:2];
							guard_bit = magnitude[1];
							sticky = magnitude[0];
						end
						3: begin
							retained = magnitude[6:3];
							guard_bit = magnitude[2];
							sticky = |magnitude[1:0];
						end
						4: begin
							retained = magnitude[7:4];
							guard_bit = magnitude[3];
							sticky = |magnitude[2:0];
						end
						5: begin
							retained = {1'b0, magnitude[7:5]};
							guard_bit = magnitude[4];
							sticky = |magnitude[3:0];
						end
						6: begin
							retained = {2'b00, magnitude[7:6]};
							guard_bit = magnitude[5];
							sticky = |magnitude[4:0];
						end
						7: begin
							retained = {3'b000, magnitude[7]};
							guard_bit = magnitude[6];
							sticky = |magnitude[5:0];
						end
						8: begin
							guard_bit = magnitude[7];
							sticky = |magnitude[6:0];
						end
						default:
							;
					endcase
					rounded = {1'b0, retained} + sv2v_cast_5(guard_bit && (sticky || retained[0]));
					if (exponent < -6) begin
						if (rounded >= 8) begin
							fp8_pack8 = {sign, 7'h08};
							_sv2v_jump = 2'b11;
						end
						if (_sv2v_jump == 2'b00) begin
							fp8_pack8 = {sign, 4'b0000, rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
					end
					if (_sv2v_jump == 2'b00) begin
						if (rounded[4]) begin
							rounded = rounded >> 1;
							exponent = exponent + 1'b1;
						end
						if ((exponent > 8) || ((exponent == 8) && (rounded > 14))) begin
							fp8_pack8 = {sign, 7'h7e};
							_sv2v_jump = 2'b11;
						end
						if (_sv2v_jump == 2'b00) begin
							encoded = sv2v_cast_4_signed(exponent + 7'sd7);
							fp8_pack8 = {sign, encoded, rounded[2:0]};
							_sv2v_jump = 2'b11;
						end
					end
				end
			end
		end
	endfunction
	function automatic [7:0] fp8_mul;
		input reg [7:0] a;
		input reg [7:0] b;
		reg [3:0] ma;
		reg [3:0] mb;
		reg [7:0] product;
		reg signed [6:0] ea;
		reg signed [6:0] eb;
		reg [0:1] _sv2v_jump;
		begin
			_sv2v_jump = 2'b00;
			if (fp8_is_nan(a[6:0]) || fp8_is_nan(b[6:0])) begin
				fp8_mul = FP8_QNAN;
				_sv2v_jump = 2'b11;
			end
			if (_sv2v_jump == 2'b00) begin
				ma = {a[6:3] != 0, a[2:0]};
				mb = {b[6:3] != 0, b[2:0]};
				ea = (a[6:3] == 0 ? -7'sd9 : $signed({3'b000, a[6:3]}) - 7'sd10);
				eb = (b[6:3] == 0 ? -7'sd9 : $signed({3'b000, b[6:3]}) - 7'sd10);
				product = ma * mb;
				fp8_mul = fp8_pack8(a[7] ^ b[7], product, ea + eb);
				_sv2v_jump = 2'b11;
			end
		end
	endfunction
	wire accumulate = exec_inst_in[5];
	wire [1:0] operation = exec_inst_in[4:3];
	wire [2:0] activation = exec_inst_in[2:0];
	assign exec_rdy = rst_n;
	function automatic [7:0] activate;
		input reg [7:0] x;
		input [2:0] op;
		reg signed [6:0] quarter_scale;
		reg [7:0] quarter;
		reg [7:0] sigmoid;
		begin
			quarter_scale = (x[6:3] == 0 ? -7'sd11 : $signed({3'b000, x[6:3]}) - 7'sd12);
			quarter = fp8_pack8(x[7], {4'b0000, x[6:3] != 0, x[2:0]}, quarter_scale);
			sigmoid = fp8_add(quarter, 8'h30);
			case (op)
				3'b001: activate = (x[7] ? FP8_ZERO : x);
				3'b010: activate = (x[6:0] > 7'h38 ? {x[7], 7'h38} : x);
				3'b011: activate = (sigmoid[7] ? FP8_ZERO : (sigmoid[6:0] > 7'h38 ? 8'h38 : sigmoid));
				3'b100: activate = (!x[7] && (x[6:0] != 0) ? 8'h38 : FP8_ZERO);
				default: activate = x;
			endcase
			if (fp8_is_nan(x[6:0]))
				activate = FP8_QNAN;
		end
	endfunction
	genvar _gv_lane_2;
	generate
		for (_gv_lane_2 = 0; _gv_lane_2 < 1; _gv_lane_2 = _gv_lane_2 + 1) begin : lanes
			localparam lane = _gv_lane_2;
			reg [7:0] input_reg;
			reg [7:0] weight_reg;
			reg [7:0] acc_reg;
			wire multiply = operation == 2'b10;
			wire [7:0] product = fp8_mul(input_reg, weight_reg);
			wire [7:0] add_a = (multiply ? product : input_reg);
			wire [7:0] add_b = (multiply ? acc_reg : {weight_reg[7] ^ (operation == 2'b01), weight_reg[6:0]});
			wire [7:0] sum = fp8_add(add_a, add_b);
			wire [7:0] result = (multiply && !accumulate ? product : sum);
			always @(posedge clk)
				if (!rst_n) begin
					input_reg <= 0;
					weight_reg <= 0;
					acc_reg <= 0;
					data_out[lane * 8+:8] <= 0;
				end
				else begin
					if (data_in_val) begin
						if (is_weight)
							weight_reg <= data_in[lane * 8+:8];
						else
							input_reg <= data_in[lane * 8+:8];
					end
					if (exec_inst_in_val) begin
						acc_reg <= result;
						data_out[lane * 8+:8] <= activate(result, activation);
					end
				end
		end
	endgenerate
	always @(posedge clk)
		if (!rst_n)
			data_out_val <= 1'b0;
		else
			data_out_val <= exec_inst_in_val;
endmodule
module mem_itf (
	clk,
	rst_n,
	read_en,
	write_en,
	rdy,
	addr,
	device,
	write_data,
	read_data,
	read_data_val,
	qspi_req_val,
	qspi_req_rdy,
	qspi_req_write,
	qspi_req_addr,
	qspi_req_device,
	qspi_req_data,
	qspi_read_data,
	qspi_read_data_val
);
	input wire clk;
	input wire rst_n;
	input wire read_en;
	input wire write_en;
	output wire rdy;
	input wire [23:0] addr;
	input wire [1:0] device;
	input wire [7:0] write_data;
	output reg [7:0] read_data;
	output reg read_data_val;
	output wire qspi_req_val;
	input wire qspi_req_rdy;
	output reg qspi_req_write;
	output wire [23:0] qspi_req_addr;
	output wire [1:0] qspi_req_device;
	output wire [7:0] qspi_req_data;
	input wire [7:0] qspi_read_data;
	input wire qspi_read_data_val;
	localparam [1:0] IDLE = 0;
	localparam [1:0] SEND = 1;
	localparam [1:0] WAIT = 2;
	reg [1:0] state;
	localparam integer LANE_BITS = 1;
	reg [LANE_BITS - 1:0] lane_index;
	reg [7:0] write_buffer;
	assign rdy = rst_n && (state == IDLE);
	assign qspi_req_val = rst_n && (state == SEND);
	function automatic [23:0] sv2v_cast_24;
		input reg [23:0] inp;
		sv2v_cast_24 = inp;
	endfunction
	assign qspi_req_addr = addr + sv2v_cast_24(lane_index);
	assign qspi_req_device = device;
	assign qspi_req_data = write_buffer[lane_index * 8+:8];
	always @(posedge clk)
		if (!rst_n) begin
			state <= IDLE;
			qspi_req_write <= 0;
			lane_index <= 0;
			write_buffer <= 0;
			read_data <= 0;
			read_data_val <= 0;
		end
		else begin
			read_data_val <= 0;
			case (state)
				IDLE:
					if (read_en || write_en) begin
						qspi_req_write <= write_en;
						write_buffer <= write_data;
						lane_index <= 0;
						state <= SEND;
					end
				SEND:
					if (qspi_req_rdy)
						state <= WAIT;
				WAIT:
					if (qspi_read_data_val) begin
						if (!qspi_req_write)
							read_data[lane_index * 8+:8] <= qspi_read_data;
						if (lane_index == 1'sd0) begin
							read_data_val <= !qspi_req_write;
							state <= IDLE;
						end
						else begin
							lane_index <= lane_index + 1'b1;
							state <= SEND;
						end
					end
				default: state <= IDLE;
			endcase
		end
endmodule
module qspi_ctrl (
	clk,
	rst_n,
	req_val,
	req_rdy,
	req_write,
	req_addr,
	req_device,
	req_data,
	read_data,
	read_data_val,
	sck,
	flash_sc_n,
	psram_a_sc_n,
	psram_b_sc_n,
	dq_in,
	dq_out,
	dq_oe
);
	input wire clk;
	input wire rst_n;
	input wire req_val;
	output wire req_rdy;
	input wire req_write;
	input wire [23:0] req_addr;
	input wire [1:0] req_device;
	input wire [7:0] req_data;
	output wire [7:0] read_data;
	output reg read_data_val;
	output reg sck;
	output reg flash_sc_n;
	output reg psram_a_sc_n;
	output reg psram_b_sc_n;
	input wire [3:0] dq_in;
	output reg [3:0] dq_out;
	output reg [3:0] dq_oe;
	localparam [3:0] IDLE = 0;
	localparam [3:0] SELECT = 1;
	localparam [3:0] CMD = 2;
	localparam [3:0] ADDR = 3;
	localparam [3:0] DUMMY = 4;
	localparam [3:0] DATA = 5;
	localparam [3:0] STATUS = 6;
	localparam [3:0] DESELECT = 7;
	localparam [3:0] CHECK = 8;
	localparam [2:0] MEMORY = 0;
	localparam [2:0] WAIT_READY = 1;
	localparam [2:0] WRITE_ENABLE = 2;
	localparam [2:0] CHECK_ENABLE = 3;
	localparam [2:0] WAIT_PROGRAM = 4;
	reg [3:0] state;
	reg [2:0] operation;
	reg [1:0] chip;
	reg write_reg;
	reg [7:0] data_shift;
	reg [1:0] status_shift;
	reg [4:0] cycles_left;
	assign read_data = data_shift;
	wire is_ram = chip[1];
	wire [7:0] memory_opcode = (is_ram ? (write_reg ? 8'h02 : 8'h0b) : (write_reg ? 8'h32 : 8'h6b));
	wire [23:0] address = (is_ram ? {1'b0, req_addr[22:0]} : req_addr[23:0]);
	wire [2:0] address_nibble_index = (is_ram ? cycles_left[2:0] : cycles_left[4:2]);
	wire [3:0] address_nibble = address[{address_nibble_index, 2'b00}+:4];
	wire [7:0] command = (operation == MEMORY ? memory_opcode : (operation == WRITE_ENABLE ? 8'h06 : 8'h05));
	assign req_rdy = rst_n && (state == IDLE);
	always @(*) begin
		dq_out = 4'b1100;
		dq_oe = 4'b0000;
		case (state)
			CMD:
				if (is_ram) begin
					dq_out = (cycles_left[0] ? command[7:4] : command[3:0]);
					dq_oe = 4'b1111;
				end
				else begin
					dq_out[0] = command[cycles_left[2:0]];
					dq_oe = 4'b1101;
				end
			ADDR:
				if (is_ram) begin
					dq_out = address_nibble;
					dq_oe = 4'b1111;
				end
				else begin
					dq_out[0] = address_nibble[cycles_left[1:0]];
					dq_oe = 4'b1101;
				end
			DATA:
				if (write_reg) begin
					dq_out = data_shift[7-:4];
					dq_oe = 4'b1111;
				end
			STATUS: dq_oe = 4'b1101;
			default:
				;
		endcase
	end
	always @(posedge clk)
		if (!rst_n) begin
			state <= IDLE;
			operation <= MEMORY;
			chip <= 0;
			write_reg <= 0;
			data_shift <= 0;
			status_shift <= 0;
			cycles_left <= 0;
			read_data_val <= 0;
			sck <= 0;
			flash_sc_n <= 1;
			psram_a_sc_n <= 1;
			psram_b_sc_n <= 1;
		end
		else begin
			read_data_val <= 0;
			case (state)
				IDLE:
					if (req_val && req_rdy) begin
						chip <= req_device;
						write_reg <= req_write;
						data_shift <= req_data;
						operation <= (req_device[1] ? MEMORY : WAIT_READY);
						state <= SELECT;
					end
				SELECT: begin
					flash_sc_n <= is_ram;
					psram_a_sc_n <= chip != 2'b10;
					psram_b_sc_n <= chip != 2'b11;
					sck <= 0;
					cycles_left <= (is_ram ? 1 : 7);
					state <= CMD;
				end
				CMD, ADDR, DUMMY, DATA, STATUS: begin
					sck <= !sck;
					if (!sck) begin
						if ((state == DATA) && !write_reg)
							data_shift <= {data_shift[3:0], dq_in};
						if (state == STATUS)
							status_shift <= {status_shift[0], dq_in[1]};
					end
					else if (cycles_left != 0) begin
						cycles_left <= cycles_left - 1'b1;
						case (state)
							DATA:
								if (write_reg)
									data_shift <= {data_shift[3:0], 4'b0000};
							default:
								;
						endcase
					end
					else
						case (state)
							CMD:
								if (operation == MEMORY) begin
									cycles_left <= (is_ram ? 5 : 23);
									state <= ADDR;
								end
								else if (operation == WRITE_ENABLE)
									state <= DESELECT;
								else begin
									cycles_left <= 7;
									state <= STATUS;
								end
							ADDR:
								if (write_reg) begin
									cycles_left <= 1;
									state <= DATA;
								end
								else begin
									cycles_left <= (is_ram ? 3 : 7);
									state <= DUMMY;
								end
							DUMMY: begin
								cycles_left <= 1;
								state <= DATA;
							end
							DATA: state <= DESELECT;
							STATUS: state <= DESELECT;
							default: state <= DESELECT;
						endcase
				end
				DESELECT: begin
					flash_sc_n <= 1;
					psram_a_sc_n <= 1;
					psram_b_sc_n <= 1;
					state <= CHECK;
				end
				CHECK:
					case (operation)
						MEMORY:
							if (!is_ram && write_reg) begin
								operation <= WAIT_PROGRAM;
								state <= SELECT;
							end
							else begin
								read_data_val <= 1;
								state <= IDLE;
							end
						WAIT_READY: begin
							if (!status_shift[0])
								operation <= (write_reg ? WRITE_ENABLE : MEMORY);
							state <= SELECT;
						end
						WRITE_ENABLE: begin
							operation <= CHECK_ENABLE;
							state <= SELECT;
						end
						CHECK_ENABLE: begin
							if (!status_shift[0] && status_shift[1])
								operation <= MEMORY;
							else
								operation <= WAIT_READY;
							state <= SELECT;
						end
						WAIT_PROGRAM:
							if (status_shift[0])
								state <= SELECT;
							else begin
								read_data_val <= 1;
								state <= IDLE;
							end
						default: state <= IDLE;
					endcase
				default: begin
					state <= IDLE;
					sck <= 0;
					flash_sc_n <= 1;
					psram_a_sc_n <= 1;
					psram_b_sc_n <= 1;
				end
			endcase
		end
endmodule
